INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "青空の下で謁見", 91002, "フリーマーケット会場", 0, 2, 20063115, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 10118, 7, 2834, 8, "ペコリーヌとの出会い", 1, 5118061);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "未来の騎空団\nマスコット？", 91002, "フリーマーケット会場", 0, 2, 20063115, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 10118, 7, 2835, 8, "マホとの出会い", 1, 5118062);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "お嬢さまからの\n緊急依頼", 91002, "ランドソル市街地", 0, 2, 20063115, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 10118, 7, 2837, 8, "アキノとの出会い", 1, 5118063);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "黄金色の悩みごと", 91002, "フリーマーケット会場", 0, 2, 20063115, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 10118, 18, 4108402, 8, "ジュンとの出会い", 1, 5118064);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "白熱！　格闘大会！", 91002, "フリーマーケット会場", 0, 2, 20063115, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 10118, 18, 4107402, 8, "カオリとの出会い", 1, 5118065);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "祭り太鼓はオーエドの華", 91002, "オーエド町", 1, 2, 20063115, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 10118, 16, 9000227, 8, "ニノンとの出会い", 1, 5118066);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "人気者は遅れて\nやってくる", 91002, "フリーマーケット会場", 0, 3, 20063115, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 10118, 19, 2101181, 8, "スズナとの出会い", 1, 5118067);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "巫女・ミーツ・魔法少女", 91002, "ランドソル市街地", 0, 3, 20063115, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 10118, 18, 4109402, 8, "ナナカとの出会い", 1, 5118068);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "ネズ耳は二度なくなる", 91002, "フリーマーケット会場", 0, 3, 20063115, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 10118, 18, 4305402, 8, "キャル＆コッコロとの出会い", 1, 5118069);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "この出会いにカンパイ！", 91002, "ランドソル市街地", 0, 3, 20063115, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 10118, 18, 4101402, 8, "ユカリとの出会い", 1, 5118070);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "陰陽アンサンブル", 91002, "ランドソル市街地", 0, 3, 20063115, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 10118, 18, 4106402, 8, "アオイとの出会い", 1, 5118071);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (40, "運試し十番勝負！", 91002, "フリーマーケット会場", 1, 3, 20063115, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 10118, 7, 2836, 8, "シノブとの出会い", 1, 5118072);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (0, "彼女たちの新たな日常", 0, 0, 0, 1, 20063115, 0, 10118, 0, 0, 0, "オープニング", 0, 5118600);
